	["tid#SeasonChapterDes_101"]="江湖之大，恰是一展宏图之处。",
	["tid#SeasonChapterDes_102"]="一展身手，闻名江湖指日可待。",
	["tid#SeasonChapterDes_103"]="初有所成，不负数载苦练之功。",
	["tid#SeasonChapterDes_104"]="得心应手，纵横江湖如鱼得水。",
	["tid#SeasonChapterDes_105"]="功成名就，多年宿愿一朝得偿。",
	["tid#SeasonDes_01"]="1、每个赛季的赛季旅程中均会包含若干章节的成就任务，成就任务以赛季为周期进行刷新；\n\n2、少侠需要完成章节中所有的成就任务才能领取该章节对应的专属成就奖励并解锁下一章节。在章节未解锁时，未解锁章节的任务进度仍然会被记录；\n\n3、成就任务的章节有限时章节与非限时章节之分。限时章节的任务以及奖励只能在当前赛季完成并且领取，请少侠留意奖励上方的限时标志；\n\n4、若在赛季结束时，少侠没能成功完成成就任务，非限时章节的任务进度会被保留，而限时章节的任务进度则会被清除；\n\n5、在后续赛季，少侠可以在往期旅程中回顾并继续完成非限时章节的成就任务并领取除赛季币以外的相关奖励。往期旅程中最多储存过往5期的赛季旅程；\n\n6、部分成就任务在当前赛季完成后会获得赛季币奖励。每个赛季结束时，当赛季剩余的赛季币将会清除并以1:100的比例转换成元宝并通过邮件发放给少侠。\n\n7、赛季币可以用于兑换赛季商店中的商品，赛季商店每赛季补货一次；\n\n8、风云录中会记录每位少侠的成就完成进度，排名规则为：章节进度靠前的少侠，排名在前；若章节进度一致，则该章节成就任务进度靠前的少侠，排名在前；若该章节成就任务进度一致，则完成时间靠前的少侠，排名在前；成就进度最快的前20名少侠将会获得赛季旅程排名奖励，该奖励会在赛季结束后通过邮件进行发放；\n",
	["tid#Equipcommon_1"]="防具洗练概率\n觉醒前：绿60.6%，蓝35%，紫3.8%，金0.6%\n觉醒后：绿0%，蓝10.5%，紫80%，金9.5%\n\n武器洗练概率\n觉醒前：绿64%，蓝30%，紫5%，金1%\n觉醒后：绿0%，蓝16%，紫64%，金20%\n\n洗练规则\n洗练：改变未被锁定的随机词缀，每增加一个锁定词缀，消耗都会提高\n高级洗练：改变未被锁定的随机词缀和核心词缀，消耗不会改变\n批量洗练：同时进行五次洗练操作，并获得五个随机的洗练结果",
	["tid#Equipcommon_2"]="1.只能熔炼闲置的白色品质的装备，熔炼后将获得一定数量的洗练石，同时有概率获得高级洗练石\n\n2.分解突破后的装备，将返还突破过程中使用的灵玉\n\n3.高级洗练石产出概率\n无阵营防具：20%\n无阵营武器：40%\n阵营防具：50%\n阵营武器：100%",
	["tid#FateStarRule_1"]="1.当侠客的经脉、羁绊、品质达到标准时，侠客将可以领悟天命，开启化星\n\n经脉畅通：经脉突破至圆满\n情缘已了：羁绊等级达到15级\n功力至臻：侠客品质达到彩品五星\n\n2.每个侠客均有自身对应的星辰，当星辰中有任一侠客领悟天命，此星辰被点亮\n\n3.星辰将根据组中天命侠客的数量，提高天命侠客的基础属性\n1名侠客：10%\n2名侠客：15%\n3名侠客：20%\n4名侠客：25%\n\n4.侠客领悟天命后可最多获得四个天命技能，解锁技能的数量与天命侠客数量相同\n\n5.玩家拥有四名天命侠客后，将在化星界面开启星楼建造功能，每加盖一层星楼，天命侠客的基础属性将获得提升\n\n6.当观星楼层数达到需求时，可以消耗天命星石解锁宗师栏位；\n\n7.已天命的侠客可以本任命为宗师，被任命的宗师可以携带一个侠客，被携带侠客的攻击、防御、血量的一部分会加成到宗师侠客身上；\n\n8.若携带的是同类型的侠客，则被携带侠客属性的30%会加成给宗师侠客，若携带的是非同类型的侠客，则只有百分之15%\n\n9.被携带侠客本身不会有属性加成；",
	["tid#ChuanGongDianDes_1"]="每拥有一个彩品侠客/彩品秘籍/神兵，等级上限增加5/1/1级",
	["tid#ChuanGongDianDes_2"]="每拥有一个彩品侠客/彩品秘籍/神兵/天命侠客，等级上限增加5/1/1/5级",
	["tid#SwordDes1"]="1.古剑现世为古剑联动活动中的主线玩法，通关古剑现世后，开启剑魔地宫玩法\n\n2.玩法分为三个阶段，完成每个阶段后解锁下一阶段内容，每个阶段的目标展示在界面右侧任务栏\n\n3.点击地图上的建筑选择需要挑战的关卡，不同关卡的解锁条件不同，部分关卡需要先通过上一关卡后解锁\n\n4.关卡挑战过程中会获得联动侠客的帮助\n\n5.首次通关会获得当前关卡的奖励，重复挑战不会获得更多奖励",
	["tid#SwordDes2"]="1.剑魔地宫总共分为九层，其中怪物的强度将根据本区玩家的整体水平进行匹配\n\n2.活动期间，剑魔地宫将开放两轮，每轮结束时，将结算本轮通关奖励\n\n3.通关奖励将根据玩家实际完成的层数进行结算，每完成一层，奖励累加一种\n\n4.剑魔地宫中，每日被击败的侠客不能再次上阵，直至次日侠客状态将刷新，或使用神像建筑复活\n\n5.战斗中损失的血量将一直保持，直至使用泉水恢复，或等待至次日刷新\n\n6.剑魔地宫中可遇到剑魔熔炉，驻守一名侠客可获得属性提升，直至通关地宫，驻守的侠客在本轮地宫中将无法上阵\n\n7.剑魔地宫中可遇到祝福使者，可挑选心仪的增益效果，每种增益效果均有战斗场次限制\n\n8.玩家可雇佣佣兵，但佣兵侠客最多只可雇佣五名，大于五名后需要替换一名已有的佣兵\n\n9.佣兵侠客不可用来驻守剑魔熔炉，也不能通过神像复活",
	["tid#SwordDes3"]="1.在煞剑出鞘活动中，根据煞剑上弹出的提示气泡，点击[月亮][熔炉][寒冰]进行互动\n\n2.互动后，根据互动正确与否，为玩家发放互动奖励，奖励将从奖池中随机一种\n\n3.互动正确，每次获得双倍奖励，互动错误则获得单倍奖励\n\n4.玩家每次互动可获得个人积分，当积分达到指定分数时获得里程碑奖励，互动正确积10分，错误积5分\n\n5.玩家每日可与煞剑互动3次",
	["tid#SwordThym_des1"]="1.桃花一梦每日可参与10次，当日未使用次数将累计，最多累计至99次\n\n2.在桃花一梦中，玩家将体验武侠世界中一名侠客的一生，每次获得新的结局，将获得额外的结局奖励\n\n3.玩家每次模拟人生，将从10个天赋中选择3个天赋，不同的天赋将影响人生的经历\n\n4.每轮人生结束后，玩家可在当次3个天赋中选择其中1个进行继承\n\n5.每轮人生结束后将根据具体的属性情况和人生成就，结算评分，评分越高对应的结算奖励将会更丰厚",
	["tid#MoneyGuide_149"]="赛季币",
	["tid#MoneyGuide_153"]="玄铁尘",
	["tid#MoneyGuide_150"]="称号碎片",
	["tid#MoneyGuide_1149"]="赛季旅程中获得的信物，可以在赛季商店中兑换商品",
	["tid#MoneyGuide_1150"]="称号碎片，可在指定商店中兑换称号",
	["tid#MoneyGuide_1153"]="玄铁尘是神兵图鉴升级所必需的,可以在神兵界面提升图鉴等级",
	["tid#MoneyGuide_155"]="剑气碎片",
	["tid#ShopTypeName_14"]="赛季商店",
	["tid#ShopTypeDes_01"]="赛季币每赛季都会清零，请少侠合理使用！",
	["tid#ATTDes_01"]="内伤减免上限为   90%\n外伤减免上限为   90%\n伤害减免上限为   90%\n闪避率上限为     80%",
	["tid#TowerActiveDes_01"]="1.天机秘境共355层，只有通关当前层数后，才可挑战下一层；\n\n2.天机秘境的进度会由本服所有玩家共享，当任意一名玩家通关一层后，该服务器中的所有玩家都会通关该层数；\n\n3.每一层的首个通关者会被记录，并展示在该层数的界面上，若有多个玩家同时进行战斗，则战斗最快的玩家才会被记录；\n\n4.天机秘境中没有掉落奖励，但在通关指定层数，会解锁天机秘宝中的奖励，该奖励解锁后，服务器中的所有玩家都可以领取；\n\n5.天机秘境中，只能使用武林谱中指定的侠客进行战斗，且武林谱中的侠客数据会从本服关卡排名前100的玩家的数据中选取；",
	["tid#TowerActiveDes_02"]="1.每一期开始时，群英谱中会指定若干名侠客供玩家选择；\n\n2.群英谱中的侠客确定后，会将本服中所有玩家的侠客战力进行排行，找出每个侠客战斗力最高版本，并将该侠客的属性复制进群英谱中，供本服所有玩家使用；\n\n3.复制的侠客属性包括：等级、品质、经脉、装备、秘籍等；\n\n\n4.天机秘境中称号、帮会神炉属性无法生效，已解锁的上古遗物会暂时提升到最高等级，以上效果会在离开天机秘境时失效；\n\n5.每天晚上23点，会重新对群英谱中的侠客进行排名，并同步属性；\n\n6.群英谱中侠客有最低等级限制，若本服所有玩家的卡牌都未达到最低等级需求，则系统会为该服务器的玩家分配一位援兵，供玩家使用；\n\n7.群英谱中的侠客只能在天机秘境中使用，离开天机秘境后会消失；",
	["tid#TowerActiveDes_03"]="1.天机觅宝中的奖励为全服奖励，当本服中任一玩家达成领取条件时，则本服中的所有玩家都可以领取该奖励；\n\n2.活动结束时，若仍有奖励未领取，则系统会将未领取的奖励通过邮件发放给玩家；\n\n",
	["tid#TowerActiveDes_04"]="1.天机秘榜分为跨服榜和贡献榜两个；\n\n2.跨服榜中会记录天机秘境玩法规定的跨服组中，所有服务器的冲层进度，并以此进行排名；\n\n3.每个服务器中，通关最高层数的玩家信息会展示在跨服榜中；\n\n4.贡献榜未本服排行榜，该排行榜会记录玩家获得首通的数量，并以此进行排名；",
