	["tid#QuestSeasonName_2606"]="势不可挡",
	["tid#QuestSeasonName_2607"]="情同手足·二",
	["tid#QuestSeasonName_2608"]="快意恩仇",
	["tid#QuestSeasonName_2609"]="财源广进",
	["tid#QuestSeasonName_2610"]="驰骋江湖·六",
	["tid#QuestSeasonDes_2601"]="【第二赛季第三周开启】苗疆炎火积分达到600",
	["tid#QuestSeasonDes_2602"]="【第二赛季第三周开启】苗疆寒山积分达到600",
	["tid#QuestSeasonDes_2603"]="【第二赛季第三周开启】苗疆森罗积分达到600",
	["tid#QuestSeasonDes_2604"]="【第二赛季第三周开启】苗疆万岛积分达到600",
	["tid#QuestSeasonDes_2605"]="【第二赛季第三周开启】累计洗练装备50次",
	["tid#QuestSeasonDes_2606"]="【第二赛季第三周开启】在五行天赛中获得20次胜利",
	["tid#QuestSeasonDes_2607"]="任意6个侠客好感度达到8级",
	["tid#QuestSeasonDes_2608"]="争锋论剑积分达到2400分",
	["tid#QuestSeasonDes_2609"]="【第二赛季第三周开启】快速挂机14次",
	["tid#QuestSeasonDes_2610"]="通关主线39-48",
	["tid#SeasonChapterName_106"]="第六章：纵横江湖",
	["tid#SeasonChapterDes_106"]="振臂高呼，江湖豪侠皆来相助。",
	["tid#YinYangTowerTitle_1"]="极阴之塔",
	["tid#YinYangGuardName_1"]="极阴守卫",
	["tid#YinYangGuardDes_1"]="极阴之塔的守卫，将其击败后可以获得大量奖励，并获得其携带的奇物。",
	["tid#YinYangTowerTitle_2"]="极阳之塔",
	["tid#YinYangGuardName_2"]="极阳守卫",
	["tid#YinYangGuardDes_2"]="极阳之塔的守卫，将其击败后可以获得大量奖励，并获得其携带的奇物。",
	["tid#OpenConditionName_244"]="极阳之塔",
	["tid#YinYangRewardTitle_1"]="极阴礼包",
	["tid#YinYangRewardTitle_2"]="极阳礼包",
	["tid#YinYangMainDetails_1"]="1.极阴之塔共150层，只有通关当前层数后，才可挑战下一层；\n\n2.极阴之塔只可使用阴系侠客进行挑战；\n\n3.极阴之塔中不可使用好友门客，但每日会开放系统助战侠客；\n\n4.系统助战侠客不限制上阵人数（最大为5）、上阵次数，助战侠客的等级与玩家拥有侠客的最大等级（最大等级超过300时按照300计算）、活动开放天数正相关；\n\n5.排行榜根据通关层数排行，多名玩家在同一层数时比较玩家所有阴卡的总战力（同一名阴系角色取战力的历史最高值），战力高的玩家排在前面；\n\n6.极阴之塔开放六天，并有一天的展示期，共七天，展示期间无法进行挑战；\n\n7.排名奖励将在展示期开始时发放，未领取的其他奖励将在展示期结束后发放；",
	["tid#YinYangMainDetails_2"]="1.极阳之塔共150层，只有通关当前层数后，才可挑战下一层；\n\n2.极阳之塔只可使用阳系侠客进行挑战；\n\n3.极阳之塔中不可使用好友门客，但每日会开放系统助战侠客；\n\n4.系统助战侠客不限制上阵人数（最大为5）、上阵次数，助战侠客的等级与玩家拥有侠客的最大等级（最大等级超过300时按照300计算）、活动开放天数正相关；\n\n5.排行榜根据通关层数排行，多名玩家在同一层数时比较玩家所有阳卡的总战力（同一名阳系角色取战力的历史最高值），战力高的玩家排在前面；\n\n6.极阳之塔开放六天，并有一天的展示期，共七天，展示期间无法进行挑战；\n\n7.排名奖励将在展示期开始时发放，未领取的其他奖励将在展示期结束后发放；",
	["tid#YinYangRewardDetails_1"]="1.活动结束时，若仍有奖励未领取，则系统会将未领取的奖励通过邮件发放给玩家；",
	["tid#YinYangRewardDetails_2"]="1.活动结束时，若仍有奖励未领取，则系统会将未领取的奖励通过邮件发放给玩家；",
	["tid#YinYangTowerTitle_3"]="木水之塔",
	["tid#YinYangGuardName_3"]="木水守卫",
	["tid#YinYangGuardDes_3"]="木水之塔的守卫，将其击败后可以获得大量奖励，并获得其携带的奇物。",
	["tid#YinYangMainDetails_3"]="1.木水之塔共150层，只有通关当前层数后，才可挑战下一层；\n\n2.木水之塔只可使用木系、水系侠客进行挑战；\n\n3.木水之塔中不可使用好友门客，但每日会开放系统助战侠客；\n\n4.系统助战侠客不限制上阵人数（最大为5）、上阵次数，助战侠客的等级与玩家拥有侠客的最大等级（最大等级超过300时按照300计算）、活动开放天数正相关；\n\n5.排行榜根据通关层数排行，多名玩家在同一层数时比较玩家所有木系、水系卡的总战力（同一名侠客取战力的历史最高值），战力高的玩家排在前面；\n\n6.木水之塔开放六天，并有一天的展示期，共七天，展示期间无法进行挑战；\n\n7.排名奖励将在展示期开始时发放，未领取的其他奖励将在展示期结束后发放；",
	["tid#YinYangRewardDetails_3"]="1.活动结束时，若仍有奖励未领取，则系统会将未领取的奖励通过邮件发放给玩家；",
	["tid#YinYangRewardTitle_3"]="木水礼包",
	["tid#YinYangSkipDes"]="1.当本层所有守卫的战力均小于玩家阵容战力的90%时开启快速碾压功能；\n\n2.快速碾压可以快速通关所有可碾压的层数，并且只会碾压每一层战力最高的守卫；\n\n3.当玩家不能碾压本层最高战力的守卫时停止快速碾压；\n\n4.快速碾压后的获得的道具奖励、奇物奖励统一获得；\n\n5.助战侠客的战力不计入快速碾压中；",
	["tid#LuoTianTitle_1"]="罗天摘星",
	["tid#LuoTianRewardTitle_1"]="罗天礼包",
	["tid#LuoTianMainDetails_1"]="1.罗天摘星每日获得10次挑战次数，挑战次数可以累计；\n\n2.罗天摘星只可使用指定种族的侠客进行挑战；\n\n3.点击下方重置按钮可以重置当前进度从头开始挑战，重置后返还所有已消耗的挑战次数，重置功能每日限3次，重置后无法重复获得通关奖励；\n\n4.罗天摘星的整体难度与玩家战力相关，每层分为三个关卡，难度越高的关卡可获得的积分奖励越多；\n\n5.排行榜根据挑战积分排行，多名玩家在积分相同时战力高的玩家排在前面；\n\n6.罗天摘星开放6天，并有1天的展示期，共7天，展示期间无法进行挑战；\n\n7.领取奖励时积分只计算历史最大值，重置积分并不会影响奖励领取；\n\n8.排名奖励将在展示期开始时发放，未领取的其他奖励将在展示期结束后发放；",
	["tid#LuoTianRewardDetails_1"]="1.领取奖励时积分只计算历史最大值，重置积分并不会影响奖励领取；\n\n2.活动结束时，若仍有奖励未领取，则系统会将未领取的奖励通过邮件发放给玩家；",
