	["tid#QMDJ_dec_01"]="奇门遁甲",
	["tid#QMDJ_dec_02"]="1.奇门遁甲按照赛季开启，每个赛季玩家以帮会为单位参加，每人每日可免费获得3点行动力（0点时无帮会状态无法获得行动力）；\\n\\n2.帮会成员可消耗行动力挑战地块，失败不消耗行动力；\\n\\n3.奇门遁甲每个地块中有多个敌人，需要全部消灭方可通过该地块，同时每个地块都会对应的可用种族的侠客；\\n\\n4.每完成1次挑战，需要派遣1名上阵的侠客驱散邪灵，此侠客今日无法在奇门遁甲中上阵，派遣会获得一份奖励，不派遣无法继续进行挑战；\\n\\n5.铸剑台建筑内可获得奇门法宝，奇门法宝归属于帮会，仅此帮会成员可用，离开帮会后法宝消失\\n\\n6.奇门遁甲内低于400级的侠客将提升至400级；\\n\\n7.在1个帮会领取奖励（地图宝箱、里程碑、帮派任务）后，加入新的帮会，已领取的奖励无法领取；\\n\\n8.离开帮会后，行动力将扣除至0点；\\n\\n9.新进入帮会，次日方可进入奇门遁甲\\n\\n10.探索积分达到上限不会增长，但是可继续挑战地图，增加个人贡献，帮会积分相同时按照达成时间先后排名",
	["tid#QMDJ_dec_03"]="帮派所有人合力挑战地块，每个地块有一定的敌人数量，全部击杀后解锁，解锁后帮派获得探索积分，参与挑战的人根据击杀数获得帮内贡献值",
	["tid#QMDJ_dec_04"]="赛季结束后帮派累计获得的奇门精魄将返还{1_value}至下赛季（最多{2_value}),本赛季法宝将会回收，并替换为新法宝",
	["tid#QMDJ_dec_05"]="根据选择的难度对此敌人造成伤害，帮派累计伤害达到100时敌人数量减1，超过100的伤害继承到下一条血量.核心属性包括：攻击力、生命值",
	["tid#QMDJmassifDes_or_202"]="实力强大的太阴，是奇门遁甲中最强大的生物",
