	["tid#HuashanlunjianName_154"]="剑心初现·1星",
	["tid#HuashanlunjianName_155"]="无名之辈",
	["tid#HuashanlunjianDes001"]="1.华山论剑采用段位制，根据少侠排名分为无名之辈到剑道独尊7个段位\\n\\n2.在华山论剑中获得段位后，会随时间累计演武币，段位越高，获得演武币的效率也越高；\\n\\n3.获得的演武币将存放在华山论剑奖励箱中，点击后即可领取；\\n\\n4.华山论剑宝箱中最多累计500000演武币，达到上限后无法继续累计，请及时领取；\\n\\n5.华山论剑每日会结算一次排名，根据排名发放邮件奖励；\\n\\n6.活动结束时，会根据排名信息发放总排名奖励，奖励会通过邮件发放；\\n\\n7.华山论剑设置有段位奖励，到达相应的段位后即可领取，段位奖励为一次性奖励，活动期间无法重复获得；\\n\\n8.在华山论剑中可以获得剑气碎片货币，剑气碎片可以在华山论剑商店中购买更高级的商品；\\n\\n9.活动结束后，剑气碎片也不会消失，再次开启华山论剑时仍可以用来购买商品；\\n\\n10.每日0点到1点期间，会结算排名并发放奖励，期间不可以进行战斗；\\n\\n11.华山论剑设有1天展示期，展示期间可以领取和兑换奖励，但无法进行战斗；\\n\\n12.华山论剑局内战斗采用3局2胜制，少侠可以在防御按钮中调整自己的防御阵容；\\n\\n13.进攻的少侠必须有三个以上队伍，每个队伍中至少需要1个侠客，先获得两局胜利者胜出；\\n\\n14.单局获胜条件有两个，满足其一即获胜，条件一：全灭对方侠客获得一场胜利，条件二：战斗时长为1分30秒，战斗超时防守方获胜；",
	["tid#QuestSpecialName_364001"]="在华山论剑中达到剑心初现·1星段位",
	["tid#QuestSpecialName_364002"]="在华山论剑中达到剑心初现·5星段位",
	["tid#QuestSpecialName_364003"]="在华山论剑中达到剑心初现·9星段位",
