	["tid#QuestSpecialName_364014"]="在华山论剑中达到剑气纵横··5星段位",
	["tid#QuestSpecialName_364015"]="在华山论剑中达到剑气纵横··9星段位",
	["tid#QuestSpecialName_364016"]="在华山论剑中达到剑指巅峰·1星段位",
	["tid#QuestSpecialName_364017"]="在华山论剑中达到剑指巅峰·5星段位",
	["tid#QuestSpecialName_364018"]="在华山论剑中达到剑指巅峰·9星段位",
	["tid#QuestSpecialName_364019"]="在华山论剑中达到剑道独尊段位",
	["tid#WuDaoChangRankDes001"]="1.练武场等级达到800级时进入人榜；\\n\\n2.练武场等级达到1200级时进入地榜并离开人榜；\\n\\n3.榜单依据玩家等级排名，玩家等级相同时，上榜时间早的玩家排在前面；",
	["tid#WuDaoChangRankDes002"]="1.练武场等级达到1200级时进入地榜；\\n\\n2.练武场等级达到1500级时进入天榜并离开地榜；\\n\\n3.榜单依据玩家等级排名，玩家等级相同时，上榜时间早的玩家排在前面；",
	["tid#WuDaoChangRankDes003"]="1.练武场等级达到1500级时进入天榜；\\n\\n2.榜单依据玩家等级排名，玩家等级相同时，上榜时间早的玩家排在前面；",
	["tid#mining_regin2_01"]="炎火",
	["tid#mining_regin2_02"]="寒山",
	["tid#mining_regin2_03"]="密林",
	["tid#mining_regin2_04"]="万岛",
	["tid#mining_dec_06"]="1.夺宝奇兵分为2个区域，每个区域仅可使用对应的侠客战斗，且每个区域仅可占领1个觅宝点，已占领觅宝点依然可以发起攻击，胜利后会驱逐对应位置的玩家；\\n\\n2.点击觅宝点即可挑战对应的位置驻守的玩家，胜利后即可占领觅宝点。占领后，觅宝点随着时间产生收益，具体收益可通过觅宝点界面查看；\\n\\n3.觅宝点收益分为两部分，一部分为固定收益随时间产生，一部分为随机收益，挂机中有几率产生，时间越久几率越大。珍品与极品觅宝点会掉落更高级道具，且几率更高；\\n\\n4.觅宝点收益最多保留12小时（随阿闲好感度等级提升，等级20级时达到最大24小时），超时后会自动撤离，奖励保存在【觅宝点】界面；\\n\\n5.新占领的觅宝点会存在保护时间，1级区域保护时间为6小时，2级区域保护时间为3小时，3级区域保护时间为2小时，4、5级区域保护时间为1小时；\\n\\n6.同帮会成员在同一线路会触发攻击力加成，1人时为5%攻击力，2人时为10%攻击力，3人时为20%攻击力，4人时为40%攻击力；\\n\\n7.同帮会成员在同一线路会触发收益加成，1人时为10%，2人时为20%，3人时为40%，4人时为50%；\\n\\n8.占领时长未满4小时，主动撤退后1小时内无法进攻相同觅宝点",
	["tid#mining_dec_07"]="摸鱼校尉",
	["tid#mining_dec_08"]="苗疆银帕提供1点贡献值，苗疆绣饰提供100点贡献值",
