	["tid#hejiatuanyuan2_1"]="1、团圆值获取：帮会成员通过备菜获得个人团圆值，帮派团圆值为所有帮派成员获得的团圆值总和；\n2、排名奖励规则：个人榜根据跨服组内个人获取的团圆值进行排名。帮会排行榜将根据跨服组内所有帮派团圆值进行排名；\n3、进度奖励需同时满足帮会团圆条件和个人团圆条件才可领取；\n4、注意事项：新加入帮会的第一天无法参与活动；\n5、活动结束后会通过邮件发放帮派及个人排名奖励。",
	["tid#hejiatuanyuan2_2"]="1、团圆值获取：帮会成员通过备菜获得个人团圆值，帮派团圆值为所有帮派成员获得的团圆值总和；\n2、排名奖励规则：个人榜根据跨服组内个人获取的团圆值进行排名。帮会排行榜将根据跨服组内所有帮派团圆值进行排名；\n3、进度奖励需同时满足帮会团圆条件和个人团圆条件才可领取；\n4、注意事项：新加入帮会的第一天无法参与活动；\n5、活动结束后会通过邮件发放帮派及个人排名奖励。",
