	["tid#HeroEnumerationName_3901"]="女性侠客攻击",
	["tid#New_Regional_Des_1"]="1.前尘旧忆以章节为单位，每章节又分为9个小节，对应拼图中的九个版块；\n2.版块的解锁需要达到指定的推关进度和江湖属性，且必须完成上一个小节；\n3.点击已解锁的任意小节，即可进入其中体验剧情故事；\n4.前尘旧忆中设有胆识、话术、魅力、经验、灵巧五种江湖属性，每种属性又有5个等级。部分任务和宝箱需要达到对应的属性等级才可以解锁；\n5.在前尘旧忆中完成锻炼任务可以锻炼对应的属性，锻炼需要消耗时辰；\n6.前尘旧忆中每天会有12个时辰，每天0点时会重置，当时辰用完时，则当天不可再完成锻炼任务；\n7.前尘旧忆中会有天气变化，在不同的天气下，可以对锻炼效果产影响，具体效果，可以点击右侧天机弹板查看；",
