	["Fengyun_challenge_tips"]="1.模拟赛可邀请好友摆擂切磋\n2.设置时可选择队伍数量和对战模式；\n3.对战模式可选择公平模式；\n4.在公平模式下双方拥有的卡牌等级和品阶一致；",
	["Fengyun_challenge_tips_1"]="1.风云擂台由模拟赛、个人赛、晋级赛三种擂台组成；\n2.均可邀请其他玩家前来擂台对战；",
	["Fengyun_challenge_tips_0"]="1.个人赛可邀请在线好友摆擂切磋\n2.设置时可选择队伍数量和对战模式；\n3.对战模式可选择公平模式；\n4.在公平模式下双方拥有的卡牌等级和品阶一致；",
	["Fengyun_challenge_tips_2"]="1.晋级赛最多可邀请7位在线玩家摆擂切磋；\n2.擂台中玩家大于等于4人准备房主即可开启对战，人数不满8人则为少侠选择擂台陪练上场战斗；\n3.擂台所有玩家随机匹配对手对战，战胜晋级，战败淘汰，直至剩余1人胜出；\n4.设置时可选择队伍数量和对战模式；\n5.对战模式可选择公平模式；\n6.在公平模式下双方拥有的卡牌等级和品阶一致；",
	["Fengyun_challenge_tips_no"]="努力开发中，敬请期待",
