	["tid#myth_tips"]="比赛流程：\n\n1.选拔赛：\n1）参赛时间：4月25日至4月27日\n2）参赛资格：练功房等级大于等于300级、白色品阶侠客数量大于等于5的少侠可参加比赛；\n3）局内对战采用三局两胜制，少侠可点击防御按钮设置防御阵容；\n4）在比赛中战胜比自己排名高的玩家可交换排名；\n5）选拔赛结束时排名前512名的玩家进入晋级赛。\n\n2.晋级赛：\n1）参赛时间：4月28日至4月29日\n2）4月28日为准备期间，少侠可在此期间调整参赛阵容，4月29日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前两位的晋级，排名末尾的淘汰，剩下四人进入复活赛。\n\n3.复活赛：\n1）参赛时间：4月29日至4月30日\n2）4月29日6点至24点为准备期间，少侠可在此期间调整参赛阵容，4月30日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前四位的晋级。\n\n4.淘汰赛：\n1）参赛时间：5月1日\n2）4月30日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月1日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前两位的晋级。\n\n5.半决赛：\n1）参赛时间：5月2日\n2）5月1日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月2日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名第一的晋级。\n\n6.总决赛：\n1）参赛时间：5月3日\n2）5月2日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月3日0点至6点为封阵容对战期间；\n3）最终8人依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，最后决出第一。\n\n\n局内规则：\n1.战中少侠持有的大侠侠客等级均为300级，非大侠侠客等级均为120级；\n2.进攻的少侠必须有三个以上队伍，每个队伍至少有一个侠客.\n\n奖励规则：\n1.竞猜成功和每次晋级获得一次奖励；\n2.在活动期间获得的武林通宝可以在万宝楼中兑换奖励；\n2.冠亚军将获得武林神话邀请函并有资格参与线下嘉年华活动；\n3.奖励均由邮件发放。\n\n竞猜规则：\n1.所有玩家均可参与竞猜（参赛选手可参与其他组的竞猜）；\n2.竞猜成功后获得武林通宝；\n3.武林通宝在活动结束之后会1比10的比例转换成元宝并通过邮件发放。\n",
	["tid#myth_haixuan_tips"]="比赛流程：\n\n1.选拔赛：\n1）参赛时间：4月25日至4月27日\n2）参赛资格：练功房等级大于等于300级、白色品阶侠客数量大于等于5的少侠可参加比赛；\n3）局内对战采用三局两胜制，少侠可点击防御按钮设置防御阵容；\n4）在比赛中战胜比自己排名高的玩家可交换排名；\n5）选拔赛结束时排名前512名的玩家进入晋级赛。\n\n2.晋级赛：\n1）参赛时间：4月28日至4月29日\n2）4月28日为准备期间，少侠可在此期间调整参赛阵容，4月29日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前两位的晋级，排名末尾的淘汰，剩下四人进入复活赛。\n\n3.复活赛：\n1）参赛时间：4月29日至4月30日\n2）4月29日6点至24点为准备期间，少侠可在此期间调整参赛阵容，4月30日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前四位的晋级。\n\n4.淘汰赛：\n1）参赛时间：5月1日\n2）4月30日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月1日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前两位的晋级。\n\n5.半决赛：\n1）参赛时间：5月2日\n2）5月1日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月2日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名第一的晋级。\n\n6.总决赛：\n1）参赛时间：5月3日\n2）5月2日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月3日0点至6点为封阵容对战期间；\n3）最终8人依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，最后决出第一。\n\n\n局内规则：\n1.战中少侠持有的大侠侠客等级均为300级，非大侠侠客等级均为120级；\n2.进攻的少侠必须有三个以上队伍，每个队伍至少有一个侠客.\n\n奖励规则：\n1.竞猜成功和每次晋级获得一次奖励；\n2.在活动期间获得的武林通宝可以在万宝楼中兑换奖励；\n2.冠亚军将获得武林神话邀请函并有资格参与线下嘉年华活动；\n3.奖励均由邮件发放。\n\n竞猜规则：\n1.所有玩家均可参与竞猜（参赛选手可参与其他组的竞猜）；\n2.竞猜成功后获得武林通宝；\n3.武林通宝在活动结束之后会1比10的比例转换成元宝并通过邮件发放。\n",
	["tid#myth_jinji_tips"]="1.晋级赛：\n1）参赛时间：4月28日至4月29日\n2）4月28日为准备期间，少侠可在此期间调整参赛阵容，4月29日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前两位的晋级，排名末尾的淘汰，剩下四人进入复活赛。\n\n2.复活赛：\n1）参赛时间：4月29日至4月30日\n2）4月29日6点至24点为准备期间，少侠可在此期间调整参赛阵容，4月30日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前四位的晋级。\n\n3.淘汰赛：\n1）参赛时间：5月1日\n2）4月30日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月1日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名前两位的晋级。\n\n4.半决赛：\n1）参赛时间：5月2日\n2）5月1日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月2日0点至6点为封阵容对战期间；\n3）每8人为一组，少侠需要和组内成员依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，排名第一的晋级。\n\n5.总决赛：\n1）参赛时间：5月3日\n2）5月2日6点至24点为准备期间，少侠可在此期间调整参赛阵容，5月3日0点至6点为封阵容对战期间；\n3）最终8人依次对战，局内采用三局两胜制，按照胜利场次和时间进行排名，最后决出第一。",
