	["tid#SeasaonBuffDes_1"]="1.在争锋论剑的防御阵容中时，每日结算奖励+30%；\n2.在五行地赛的防御阵容中时，每日结算奖励+30%；\n3.在五行天赛的防御阵容中时，每日结算奖励+50%；\n5.在天下演武的防御阵容中时，演武币的获取速率+30%；\n\n\n\n",
	["tid#SeasaonBuffDes_2"]="1.在争锋论剑的防御阵容中时，每日结算奖励+30%；\n2.在五行地赛的防御阵容中时，每日结算奖励+30%；\n3.在五行天赛的防御阵容中时，每日结算奖励+50%；\n4.在五行联赛的防御阵容中时，每日结算奖励+50%；\n5.在天下演武的防御阵容中时，演武币的获取速率+30%；\n\n\n\n",
	["tid#SeasaonBuffDes_3"]="1.在争锋论剑的防御阵容中时，每日结算奖励+30%；\n2.在五行地赛的防御阵容中时，每日结算奖励+30%；\n3.在五行天赛的防御阵容中时，每日结算奖励+50%；\n4.在五行联赛的防御阵容中时，每日结算奖励+50%；\n5.在天下演武的防御阵容中时，演武币的获取速率+30%；\n\n\n\n",
	["tid#SeasaonBuffDes_4"]="1.在争锋论剑的防御阵容中时，每日结算奖励+30%；\n2.在五行地赛的防御阵容中时，每日结算奖励+30%；\n3.在五行天赛的防御阵容中时，每日结算奖励+50%；\n4.在五行联赛的防御阵容中时，每日结算奖励+50%；\n5.在天下演武的防御阵容中时，演武币的获取速率+30%；\n\n\n\n",
	["tid#SeasaonBuffDes_5"]="1.在争锋论剑的防御阵容中时，每日结算奖励+30%；\n2.在五行地赛的防御阵容中时，每日结算奖励+30%；\n3.在五行天赛的防御阵容中时，每日结算奖励+50%；\n4.在五行联赛的防御阵容中时，每日结算奖励+50%；\n5.在天下演武的防御阵容中时，演武币的获取速率+30%；\n\n\n\n",
	["tid#SeasaonBuffDes_6"]="1.在争锋论剑的防御阵容中时，每日结算奖励+30%；\n2.在五行地赛的防御阵容中时，每日结算奖励+30%；\n3.在五行天赛的防御阵容中时，每日结算奖励+50%；\n4.在五行联赛的防御阵容中时，每日结算奖励+50%；\n5.在天下演武的防御阵容中时，演武币的获取速率+30%；\n\n\n\n",
	["tid#YinYangTowerTitle_4"]="金火之塔",
	["tid#YinYangGuardName_4"]="金火守卫",
	["tid#YinYangGuardDes_4"]="金火之塔的守卫，将其击败后可以获得大量奖励，并获得其携带的奇物。",
	["tid#YinYangMainDetails_4"]="1.金火之塔共150层，只有通关当前层数后，才可挑战下一层；\n\n2.金火之塔只可使用金系、火系侠客进行挑战；\n\n3.金火之塔中不可使用好友门客，但每日会开放系统助战侠客；\n\n4.系统助战侠客不限制上阵人数（最大为5）、上阵次数，助战侠客的等级与玩家拥有侠客的最大等级（最大等级超过300时按照300计算）、活动开放天数正相关；\n\n5.排行榜根据通关层数排行，多名玩家在同一层数时比较玩家所有金系、火系卡的总战力（同一名侠客取战力的历史最高值），战力高的玩家排在前面；\n\n6.金火之塔开放六天，并有一天的展示期，共七天，展示期间无法进行挑战；\n\n7.排名奖励将在展示期开始时发放，未领取的其他奖励将在展示期结束后发放；",
	["tid#YinYangRewardDetails_4"]="1.活动结束时，若仍有奖励未领取，则系统会将未领取的奖励通过邮件发放给玩家；",
