	["tid#OpenConditionName_338"]="天地战阵",
	["tid#normal_array_tips"]="1.获得阵眼侠客之后，解锁战阵；\n2.阵眼侠客品阶越高可激活的重数越高；\n3.解锁阵法后，需要在上阵时上阵阵眼和阵法要求的侠客即可激活；\n4.激活后战斗中获得阵法加成；\n5.如将阵眼侠客归隐则阵眼恢复上锁状态。",
	["tid#pubicgift_01"]="1.蓬莱集市每天会更新若干拼团礼包，可以在“我的拼团-发起拼团”中选择一个礼包发起拼团；\n\n2.发起拼团后的礼包会出现在“我的拼团”列表中，可以在此购买和放弃拼团，放弃拼团后可以重新发起新的拼团；\n\n3.发起的拼团礼包同时也会出现在“拼团大厅”中，其他玩家也可以在此加入你的拼团，加入的拼团可以在“我的拼团”列表中查看；\n\n4.在“我的拼团”列表中可以选择正在参加的拼团礼包并购买，购买之后可以邀请其他好友或发送世界聊天信息邀请其他人加入该拼团；\n\n5.当一个拼团礼包中，购买人数达到需求时，即可获得对应的代金券奖励，金额越大的礼包代金券返利越多，同一礼包的代金券奖励取最大值，不会累加；\n\n6.只有购买了拼团礼包的玩家才可获得该礼包的代金券奖励，只参加的玩家不会获得；\n\n7.当天发起的所有拼团礼包都会在晚上24点时刷新，并根据拼团结果通过邮件发放代金券奖励；\n\n8.蓬莱集市中设有全服代金券奖励，当前跨服组中的拼团礼包购买数量达到需求时，即可获得对应的代金券返利；\n\n9.全服代金券返利发放时，会计算玩家在蓬莱集市活动中花费的金额，并乘以相应的百分比，花费的金额越多，最终的返利越多；",
