	["tid#bazaar_des_001"]="1.蓬莱集市内可进行摆摊，摆摊期间会持续产生奇兽固元丹和好感度道具等；\n\n2.蓬莱集市初始为1级，只有一个摆摊位置和商铺，摆摊时可随时间获得经验，提升蓬莱集市等级，等级提升后会解锁更多的摊位和商铺；\n\n2.同一种类型的商铺共有三个等级，当解锁高等级的商铺类型后，低等级的商铺将不可使用；\n\n3.等级越高的商铺，产出的速率越高，产出道具的稀有度也越高；\n\n4.提升特权等级可以解锁最多2个额外摊位，特权等级达到5级时可解锁一个，达到13级时可解锁另外一个；\n\n5.蓬莱集市中设有每日流行商品，当摆摊产出流行商品的店铺时，则直到摆摊结束前，该店铺的产出会翻倍；\n\n6.使用加速功能可使当前店铺的摆摊时间立刻结束，并获得所有奖励，但每天可加速的次数有限,提升特权等级，每日加速次数也会增加；\n\n7.1~3级时每天可加速2次，4~6级时每天可加速3次，7~9级时每天可加速4次，10~11级时每天可加速5次，12~13级时每天可加速6次，14~15级时每天可加速7次，16~17级时每天可加速8次，18~19级时每天可加速9次，20~22级时每天可加速10次；",
