	["tid#bazaar_UpgradeDes_01"]="集市等级：1\n\n免费空地数量：1\n\n商铺列表：板车摊位\n\n蓬莱工坊产出加成：5%",
	["tid#bazaar_UpgradeDes_02"]="集市等级：2\n\n免费空地数量：2\n\n商铺列表：板车摊位、小推车、露天拉面馆\n\n蓬莱工坊产出加成：10%",
	["tid#bazaar_UpgradeDes_03"]="集市等级：3\n\n免费空地数量：2\n\n商铺列表：板车摊位、小推车、露天拉面馆、旧货地摊、赤脚医生\n\n蓬莱工坊产出加成：15%",
	["tid#bazaar_UpgradeDes_04"]="集市等级：4\n\n免费空地数量：3\n\n商铺列表：板车摊位、小推车、露天拉面馆、旧货地摊、赤脚医生、裁缝作\n\n蓬莱工坊产出加成：20%",
	["tid#bazaar_UpgradeDes_05"]="集市等级：5\n\n免费空地数量：3\n\n商铺列表：板车摊位、小推车、露天拉面馆、旧货地摊、赤脚医生、裁缝作坊、书画铺子\n\n蓬莱工坊产出加成：25%",
	["tid#bazaar_UpgradeDes_06"]="集市等级：6\n\n免费空地数量：3\n\n商铺列表：板车摊位、小推车、露天拉面馆、旧货地摊、赤脚医生、裁缝作坊、书画铺子、古玩铺子\n\n蓬莱工坊产出加成：30%",
	["tid#bazaar_UpgradeDes_07"]="集市等级：7\n\n免费空地数量：4\n\n商铺列表：板车摊位、小推车、露天拉面馆、旧货地摊、赤脚医生、裁缝作坊、书画铺子、古玩铺子\n\n蓬莱工坊产出加成：35%",
	["tid#bazaar_UpgradeDes_08"]="集市等级：8\n\n免费空地数量：4\n\n商铺列表：小木屋、杂货铺、露天拉面馆、旧货地摊、赤脚医生、裁缝作坊、书画铺子、古玩铺子\n\n蓬莱工坊产出加成：40%",
	["tid#bazaar_UpgradeDes_09"]="集市等级：9\n\n免费空地数量：5\n\n商铺列表：小木屋、杂货铺、露天拉面馆、旧货地摊、赤脚医生、裁缝作坊、书画铺子、古玩铺子\n\n蓬莱工坊产出加成：45%",
	["tid#bazaar_UpgradeDes_10"]="集市等级：10\n\n免费空地数量：5\n\n商铺列表：小木屋、杂货铺、小饭馆、当铺、赤脚医生、裁缝作坊、书画铺子、古玩铺子\n\n蓬莱工坊产出加成：50%",
