	["tid#bazaar_BuildName_803"]="古董商会",
	["tid#bazaar_BuildDes_101"]="破旧的小板车搭车的摊位，上面装了一些小零食\n\n奇兽固元丹：20/小时\n\n金币：2400/小时",
	["tid#bazaar_BuildDes_102"]="简洁的小木屋，木屋的架子上摆满了零食\n\n奇兽固元丹：35/小时\n\n金币：4200/小时",
	["tid#bazaar_BuildDes_103"]="温馨的零食商铺，里面的商品琳琅满目，承载了不少人的童年记忆\n\n奇兽固元丹：50/小时\n\n金币：6000/小时",
	["tid#bazaar_BuildDes_201"]="破旧的小推车，经常在一些走街串巷的小贩边上见到\n\n奇兽固元丹：20/小时\n\n金币：2400/小时",
	["tid#bazaar_BuildDes_202"]="普通的杂货铺，别看小，但是东西很齐全\n\n奇兽固元丹：35/小时\n\n金币：4200/小时",
	["tid#bazaar_BuildDes_203"]="几家商铺联合成立的商会，基本上只有你想不到，没有买不到的\n\n奇兽固元丹：50/小时\n\n金币：6000/小时",
	["tid#bazaar_BuildDes_301"]="路边随处可见的拉面摊，味道只能算是一般\n\n奇兽固元丹：20/小时\n\n金币：2400/小时",
	["tid#bazaar_BuildDes_302"]="平凡的小饭馆，卖的都是一些家常菜，味道虽然不算特别好，但人情味很浓\n\n奇兽固元丹：35/小时\n\n金币：4200/小时",
	["tid#bazaar_BuildDes_303"]="生意红火的大排档，天上飞的，地上跑的水里游的，应有尽有\n\n奇兽固元丹：50/小时\n\n金币：6000/小时",
	["tid#bazaar_BuildDes_401"]="回收旧物的地摊，偶尔能捡漏受到一些值钱货\n\n奇兽固元丹：20/小时\n\n金币：2400/小时 ",
	["tid#bazaar_BuildDes_402"]="一家小当铺，主要回收一些旧物，靠的就是眼里和经验\n\n奇兽固元丹：35/小时\n\n金币：4200/小时",
	["tid#bazaar_BuildDes_403"]="大型的典当行，只收贵重的东西，普通的玩意儿都进不了门\n\n奇兽固元丹：50/小时\n\n金币：6000/小时",
	["tid#bazaar_BuildDes_501"]="行走江湖的赤脚医生，祖传的大力丸包治百病\n\n奇兽固元丹：20/小时\n\n金币：2400/小时",
	["tid#bazaar_BuildDes_502"]="门面不大的医馆，医术是祖上传下来的，邻里街坊有个头疼脑热的都乐意来瞧一瞧\n\n奇兽固元丹：35/小时\n\n金币：4200/小时",
	["tid#bazaar_BuildDes_503"]="听说坐馆的是个退下来的太医，一手医术神乎其技，只要还有口气就能妙手回春\n\n奇兽固元丹：50/小时\n\n金币：6000/小时",
	["tid#bazaar_BuildDes_601"]="简陋的小作坊，做出来的衣服倒也算是简洁方便\n\n奇兽固元丹：20/小时\n\n金币：2400/小时",
	["tid#bazaar_BuildDes_602"]="有经验的裁缝开成衣铺，量体裁衣，做出来的衣服又贴身又舒服\n\n奇兽固元丹：35/小时\n\n金币：4200/小时",
	["tid#bazaar_BuildDes_603"]="远近闻名的大布行，普通的衣服冠上他们的名号就能翻好几倍\n\n奇兽固元丹：50/小时\n\n金币：6000/小时",
	["tid#bazaar_BuildDes_701"]="落魄书生开的书画摊，靠帮人画肖像、写信赚钱\n\n奇兽固元丹：20/小时\n\n金币：2400/小时",
	["tid#bazaar_BuildDes_702"]="贩卖一些小有名气的书画作品，买来几幅挂在家里可以充一些门面\n\n奇兽固元丹：35/小时\n\n金币：4200/小时",
	["tid#bazaar_BuildDes_703"]="远近闻名的书画会馆，听说光是入门都需要先考个秀才\n\n奇兽固元丹：50/小时\n\n金币：6000/小时",
	["tid#bazaar_BuildDes_801"]="简单的一块红笔铺在地上，就成了一个古玩摊摊，整个地摊上最古老的也就是这块红布了\n\n奇兽固元丹：20/小时\n\n金币：2400/小时",
	["tid#bazaar_BuildDes_802"]="有门面的古董商行，值钱的古董都摆在架子上，没钱连摸都别想摸\n\n奇兽固元丹：35/小时\n\n金币：4200/小时",
	["tid#bazaar_BuildDes_803"]="气派的商行，古董走的都是拍卖形式，据说卖的都是稀世珍宝\n\n奇兽固元丹：50/小时\n\n金币：6000/小时",
