	["tid#OpenConditionName_349"]="蓬莱集市",
	["tid#OpenConditionName_350"]="蓬莱",
	["tid#InteractGift_01"]="奇兽互动宝箱",
	["tid#InteractGift_02"]="与任意奇兽互动可获得以下材料中的随机一种：",
	["tid#HeroEnumerationName_9950"]="气势",
	["tid#HeroEnumerationName_19950"]="气势",
	["tid#MoneyGuide_1162"]="在蓬莱集市中进行开店获得，可用于提升奇兽等级，以及领悟奇兽",
	["tid#MoneyGuide_162"]="奇兽固元丹",
	["tid#money_guide_gain_1162"]="可通过蓬莱集市开店获得",
	["tid#MoneyGuide_1163"]="在蓬莱工坊中通过派遣奇兽获得，可用于在奇兽商店中兑换对应商品",
	["tid#MoneyGuide_163"]="奇兽铸币",
	["tid#money_guide_gain_1163"]="可通过蓬莱工坊派遣获得",
	["tid#PetRuleDes_1"]="1、少侠可以在蓬莱集市中通过开店获取奇兽以及奇兽升级所需的各项资源；\n\n2、少侠已获得的奇兽可在宠物大厅中进行奇兽展示，点击奇兽即可与该奇兽进行互动，查看该奇兽相关信息以及获得互动奖励；\n\n3、在奇兽中，少侠可以查看当前所拥有的所有奇兽，并对该奇兽进行升级/繁衍/归林等相关操作；\n\n4、每只奇兽初始出生时均会随机不同品质的资质，分别为紫品/橙品/红品/白品，并且跟随繁衍过程或者变异效果均有可能改变奇兽的品质以及资质；\n\n5、每类奇兽均有3类技能：\n1）斗技技能：该类技能只可在奇兽斗技中使用，在侠客对战战斗或主线关卡中无法使用相关技能\n2）协战技能：当少侠在侠客对战战斗或主线关卡中选择该奇兽进行协战时，相关技能可生效（江湖传奇/巅峰论剑暂时无法上阵奇兽）；\n3）根骨技能：该类技能可同时在奇兽斗技与侠客协战中使用；\n不同类型的技能均有不同品质，当少侠初始获得某奇兽时，必定解锁一个任意品质的斗技必杀技能，其余技能根据繁衍情况随机获得；\n\n6、技能品质以及随机概率如下所示：\n1）蓝品技能：60%\n2）紫品技能：30%\n3）橙品技能：10%\n同一技能的技能效果将会随着技能品质的提升而提升。",
	["tid#PetRuleDes_2"]="1、当前版本每类奇兽均可从初始的一代繁衍至最高五代，每次繁衍均需要两只奇兽，分别为一只主体奇兽与一只辅助奇兽，并且两只奇兽均需达到开启繁衍的最小等级；\n\n2、每次繁衍后，主体奇兽与辅助奇兽均会被放生，并繁衍一只同类新生奇兽，少侠需要重新培养该奇兽。繁衍带来的影响如下：\n\n1）每繁衍一代，奇兽拥有的技能数量必定会逐代增加1个；\n\n2）每次进行繁衍时，奇兽均有概率进行变异，变异概率由主/辅奇兽共同决定，通过【领悟】可提升双方奇兽的变异概率，但下次繁衍时只有主体奇兽的变异效果可继承；\n\n3）每次繁衍后，新生奇兽的技能将会从参与繁衍的奇兽双方拥有的技能中继承，其中斗技技能与协战技能不可叠加获得；\n\n4）若新生奇兽可获得技能的数量大于可继承的技能数量，剩余的技能将会从该奇兽的技能池中随机出一个新技能；\n\n5）新生宠物的品质由参与繁衍的主/辅奇兽的品质共同决定；\n\n3、奇兽繁衍后，需要经历一段孵化时间，孵化结束后少侠方可知晓此次孵化的各项结果 ，在孵化过程中，无法在队伍中上阵该奇兽，无法在蓬莱工坊中派遣该奇兽，无法在大厅中展示以及对该奇兽进行归林操作，但玩家可使用道具对奇兽孵化进行加速；",
	["tid#PetRuleDes_3"]="1、当代奇兽提升至指定等级开启繁衍功能时，【奇兽领悟】功能一并开启，指定等级根据奇兽的培养代数递增；\n\n2、繁衍时，奇兽有几率变异，少侠可通过【奇兽领悟】功能提高奇兽变异的几率；\n\n3、少侠可在奇兽背包中查看当前奇兽已获得的变异效果",
	["tid#PetRuleDes_4"]="1、少侠可点击【奇兽归林】按钮对奇兽进行归林操作；\n\n2、归林后，将根据奇兽当前的代数以及等级返还部分养成资源（领悟消耗资源不会返还）；\n\n3、归林后奇兽将会消失",
	["tid#PetRuleDes_5"]="1、少侠在蓬莱工坊中可派遣宠物进行劳作获得蓬莱集市的开店材料与奇兽铸币；\n\n2、少侠获得材料奖励的数量随当前派遣的奇兽数量，奇兽代数，蓬莱集市等级的提升而增多；\n\n3、派遣宠物达到上限时间后，奖励停止累计，少侠需要重新派遣奇兽进行劳作，请及时领取奖励！\n\n4、派遣中的宠物若被归林，或者繁衍，会从派遣队伍中撤回，请少侠及时补充派遣队伍！\n\n5、少侠可对派遣中的奇兽投喂饲料，饲料生效期间的所有奖励产出均可获得加成",
	["tid#notice_petbag"]="奇兽数量已经达到持有上限，请前往繁衍宠物。",
