	["tid#ChongZhiFanLiDes_1"]="1.活动期间单笔充值金额等于充值返利档位时，可在活动中领取对应档位的奖励；\n2.每个返利档位互相独立，一笔充值只能领取一个档位的奖励；\n3.当进行购买战令、礼包等消耗金额的操作时，也可完成充值返利；\n4.消耗代金券不能完成充值返利；\n5.每个档位的奖励限领取一次；\n6.活动结束后，已完成但未领取的充值返利奖励将通过邮件发放；",
