	["tid#OpenConditionName_365"]="奇兽斗技",
	["tid#PetRuleDes_6"]="1、奇兽竞技场将在少侠拥有至少一只奇兽后开启，每期竞技场持续时间与赛季时间一致，赛季结束后竞技场积分会重置；\n\n2、少侠每周可领取奇兽竞技参与次数宝箱，宝箱进度每周结束时重置，未领取的奖励会通过邮件进行发放；\n\n3、特殊规则：\n1）每期加成：每期奇兽竞技场将会针对不同种类的奇兽进行加成，相关奇兽可在进入战斗时获得描述的加成效果；\n\n2）奇兽竞技场分为2个阶段：\n第一阶段：气势比拼。在该阶段，双方对位奇兽将会直接比拼气势值大小，气势值大者为胜方。若双方气势值一致，则进攻方判定为失败。气势胜利方将会在奇兽斗技的第二阶段中，部分技能获得增强。\n第二阶段：正式战斗。奇兽双方将会在战斗中可以使用该奇兽已经随机到的斗技技能进行战斗，打败敌方所有奇兽即可判定为胜利。若达到规定时间但双方仍有奇兽存活，则进攻方被判定为失败。\n\n3）心情状态：\n每只奇兽每天会有不同的心情，少侠可以通过投喂奇兽增加该奇兽的心情，投喂后的结果将会保持整天。心情的好坏会对奇兽的气势有一定影响；",
	["tid#MoodName_1"]="不开心",
	["tid#MoodName_2"]="一般",
	["tid#MoodName_3"]="非常开心",
	["tid#MoodDes_1"]="斗技气势降低20%",
	["tid#MoodDes_2"]="斗技气势不变",
	["tid#MoodDes_3"]="斗技气势提升20%",
	["tid#OpenConditionName_372"]="风华录",
	["tid#fenghuaRuleDes_1"]="1、【风华册】可在活动中获得，部分【风华册】可在功能内花费元宝购买；\n\n2、收集同一组内的【风华册】可激活全局属性加成；",
	["tid#MoneyGuide_165"]="风华册",
	["tid#MoneyGuide_1166"]="活动中获取，收集套装后激活属性加成，可在【侠客】—【风华录】功能内查看详情",
	["tid#Qingliangxiarides_1"]="1、每日有一定挑战次数，根据挑战所造成的伤害获得伤害奖励；\n\n2、活动期间内，每日最高伤害相加计算排行榜，活动结束后发放排行榜奖励；\n\n3、每期活动，BOSS会有弱点效果；\n\n4、活动有每日任务，完成任务获得丰厚奖励，并增加战令经验，战令解锁会获得更多奖励",
