	["tid#prestige_des"]="1、共有4个威望命盘，分别对应金木水火四个种族，命盘除了可以装备对应种族的命格，金、火命盘还可以装备阳系命格，木、水命盘还可以装备阴系命格；\n\n2、威望命盘可以消耗命格碎片升级，最高等级为50级，升级除了会增加属性之外，在10、30、50级时解锁格子；\n\n3、命格共4个星级，1星命格大小为6格，共9个形状，1个低级属性；2星命格大小为5格，共9个形状，1个低级属性，1个低级或高级的属性，共2个；3星命格大小为3-4格，共9个形状，1个低级属性，1个低级或高级的属性，1个高级属性，共3个属性；4星命格大小为2格，1个形状，2个高级属性，1个定制属性；\n\n4、每个命格会对应一个英雄，每个命盘镶嵌指定英雄后可以激活羁绊，羁绊达到一定数量可以激活属性加成，联动英雄不会出现在此功能；\n\n5、命格可在编辑界面镶嵌至命盘，将命格拖入命盘后，切换为旋转模式后，点击命格可以旋转，没有冲突保存成功后属性加成生效；\n\n6、命盘评分分为3部分：命盘等级、镶嵌棋子、激活羁绊；\n\n7、命格最多持有999个，获得时超出上限会暂存在邮箱，多余命格可在背包中分解命格为碎片；\n\n8、限时棋子过期后将消失，不再提供属性加成；\n\n9、词缀库：\n低级词缀： \n攻击+1000 \n攻击+1500 \n攻击+2000 \n防御+50 \n防御+70 \n防御+100 \n生命+3000\n生命+4000 \n生命+5000 \n高级词缀： \n攻击+1.5% \n攻击+3% \n防御+1.5% \n防御+3% \n生命+1.5% \n生命+3% \n暴击率+2% \n暴击率+3% \n抗暴率+3% \n抗暴率+5%\n内伤减免+1.5% \n内伤减免+3% \n外伤减免+1.5% \n外伤减免+3% \n内伤增加+1.5% \n内伤增加+3% \n外伤增加+1.5% \n外伤增加+3% \n定制词缀： \n伤害增加+2% \n伤害减免+2% \n暴击效果+2% \n金阵营伤害增加+5% \n木阵营伤害增加+5% \n水阵营伤害增加+5% \n火阵营伤害增加+5% \n阳阵营伤害增加+5% \n阴阵营伤害增加+5% \n金阵营伤害减免+5% \n木阵营伤害减免+5% \n水阵营伤害减免+5% \n火阵营伤害减免+5% \n阳阵营伤害减免+5% \n阴阵营伤害减免+5%\n",
