	["tid#guild_high_tips"]="'1.参战资格：\n·S4赛季后服务器帮会，可在功能开启首日报名参加巅峰帮会战；\n·错过报名日帮会，可在任意时间报名参加下一轮；\n·匹配阶段无法报名\n\n2.日程规划：\n·第1天0点-24点为报名时间，报名成功进入常规赛；\n·常规赛结束进入季后赛和后备赛\n\n3.常规赛：\n·常规赛共3轮，每轮有7回合战斗；\n·每轮结束后战绩累计，重新匹配对手；\n·常规赛战绩值1-32名晋级天级赛、33-64名晋级地级赛、65-96名晋级玄季赛、97-128名晋级人极赛，128名之后进入后备赛\n\n4.季后赛：\n·季后赛共2轮，每轮有11天战斗日，进行9回合战斗；\n·第1轮每个战场前2名晋级第2轮，其余人淘汰制后备赛；\n·第2轮战绩直接决出前8名\n\n5.攻城对抗：\n1）宣战阶段：\n·有城池的帮会管理员需选择一个相邻城池宣战；\n·没有城池的帮会可选择任意一级城池宣战；\n·宣战次数和所拥有城池的最高等级相同，比如当前帮会拥有一个三级城和一个一级城，则有3次宣战机会；\n·如有多个帮会对同一座城池宣战，则战力高的帮会才能宣战成功进入布阵阶段\n2）布阵阶段：\n·参战帮会中所有成员可派遣已编辑的队伍前往宣战城池参与战斗或选择在原有驻地防御；\n3）战斗阶段：\n·此阶段持续时间为1小时，战斗此阶段所有少侠均不可操作；\n·战斗阶段结束后可查看所有战况，并根据占领城池发放本回合奖励；\n\n6.城内对战：\n·城内对战为车轮战，胜利的队伍保持胜利时的血量、人数进入下一次战斗，内力不继承，同时队伍会获得一个倦怠效果，攻击力和血量降低；\n·当城池内有一方的侠客全部被击败则战斗结束，有剩余侠客的一方获胜；\n\n7.战绩和武勋：\n·帮会每占领一个城池，根据城池等级获得战绩，常规赛第2轮开始获得战绩翻倍。季后赛每轮最后2回合战绩翻倍\n·参与巅峰战的帮会成员，局内对战中每击杀一名侠客获得1点武勋，连续击杀会额外获得武勋\n\n8.回合战斗时间：\n·21:00-11:00宣战阶段，11:00-19:00布阵阶段，19:00-20:00管理调整时间，20:00-21:00战斗阶段\n\n7.奖励规则：\n·每日任务：每日刷新，完成任务领取奖励\n·城池奖励：战斗阶段结束后根据帮会占领城池发放每日奖励，一座城池每天会额外发放一个此城池产出的宝箱，城池等级对应宝箱等级，等级越高宝箱品阶越高；\n·结算奖励：常规赛与季后赛结束后，发放排名奖励。\n'''",
