	["tid#guild_high_yaoqing"]="巅峰帮会战邀请函：\n\n恭喜少侠，您的帮会因为在帮会战中表现卓越，获得巅峰帮会战的资格\n巅峰帮会战将在【%s】开启，请及时前往天下的帮会争锋中查看。\n\n\n                                --武林闲侠开发团队",
