	["tid#OpenConditionName_361"]="阿闲课程表",
	["tid#AXianTimeTable_des_1"]="1、课程表会消耗对应功能内次数，并获得对应功能内的奖励，具体奖励仅在课程表内提供预估展示，实际获得与玩法单独本身相关；\n\n2、目前开放【玄武遗迹】、【武道场】、【侠客试炼】、【江湖传奇】功能，后续功能阿闲正在努力学习中；\n\n3、玄武遗迹扫荡：完成作业会按照剩余可用次数挑战玄武，并领取玄武英雄榜奖励；\n\n4、武道场扫荡：打通全部层数后开启扫荡，扫荡会同时消耗免费与付费次数，并消耗对应数量的元宝；\n\n5、侠客试炼：完成作业会领取全部任务奖励；\n\n6、江湖传奇：打通全部层数后开启扫荡，扫荡会完成全部日常任务，并按照保存阵容挑战上榜；",
	["tid#TitleName_30089"]="侠义无双",
