	["tid#TitlelockDes_30090"]="侠客行活动获得",
	["tid#combat_repress_Namedes1"]="侠客评分细则\n1.不同种族分数不同，四系25，阴阳40，元50\n2.侠客等级每升1级加1分，最高1000分\n3.侠客品质每提升一次加45分，最高900分\n4.经脉每提升一次加2分，最高40分\n5.好感度每提升1级增加3分，最高90分\n6.天命化星激活后，增加1200分\n7.职业进阶每进阶一次增加240分，最高1680分\n8.侠客每拥有一个皮肤增加10分，最高50分\n9.侠客每装备一个彩秘籍增加150分，最高600分\n10.神技秘籍每本增加450分\n11.侠客身上秘籍每镶嵌一本先天和绝技秘籍加50分，神技秘籍加150分，最高4000分\n12.彩品质符篆加100分，最高加400分",
	["tid#combat_repress_Namedes2"]="装备评分细则\n1.每装备一个彩品质装备增加250分，最高1250分\n2.装备每强化一级增加1分，最高25分\n3.装备每神兵强化一级增加1分，最高25分\n4.每一个装备阵营相同增加20分，最高100分\n5.武器激活核心词缀增加40分\n6.装备每个橙色品质的词缀增加35分，最高420分",
	["tid#combat_repress_Namedes3"]="全局评分细则\n1.每个威望命盘提升一级增加3分，最高600分\n2.威望命盘每装备一个四星命格增加55分，三星命格增加10分，最高5800分\n3.神兵谱每提升一级增加3分，最高3600分\n4.观星楼每提高一级增加4分，最高640分\n5.帮派祈福每提升一级增加2分，最高240分\n6.每个已激活的称号增加10分，最高增加1500分（相同只增加1遍）\n7.风华录，每个凤华册增加10分，最高60分",
	["tid#combat_repress_des"]="1.武学评分仅在玩家对抗玩法中生效\n2.上阵侠客时，5个侠客武学分数相加得出武学境界\n3.武学境界领先1级时，对全体侠客造成15%生命值伤害，最终增减伤减少10%\n4.武学境界领先2级及以上时，对全体侠客造成30%生命值伤害，最终增减伤减少20%\n5.分数分为3大类，侠客分、装备分、全局养成分。全局养成计算等级时仅计算一次",
	["tid#OpenConditionName_383"]="威望阁",
